// The moves the regulation has, as their pages show them: generated by `npm run gen-data` (`moves.data.json`), typed
// here.

import DATA from '@/data/generated/moves.data.json'
import type { MoveId } from '@/data/dex'
import type { TypeId } from '@/data/types'

export const CATEGORIES = ['physical', 'special', 'status'] as const
export type Category = (typeof CATEGORIES)[number]

/** Showdown's move flags the app shows (`MOVE_FLAGS` in `scripts/gen-data.ts`). */
export const FLAGS = [
  'contact',
  'sound',
  'punch',
  'bite',
  'slicing',
  'pulse',
  'sheerforce',
  'bullet',
  'wind',
  'powder',
  'dance',
  'heal',
  'gravity',
  'bypasssub',
  'reflectable',
  'protect',
  'charge',
  'cantusetwice',
] as const
export type Flag = (typeof FLAGS)[number]

/** Whom a move hits, as Showdown names it. */
export const TARGETS = [
  'normal',
  'any',
  'randomNormal',
  'allAdjacentFoes',
  'allAdjacent',
  'adjacentAlly',
  'adjacentAllyOrSelf',
  'self',
  'allies',
  'allySide',
  'allyTeam',
  'foeSide',
  'all',
  'scripted',
] as const
export type Target = (typeof TARGETS)[number]

export interface Move {
  type: TypeId
  category: Category
  /** 0 for status moves, and for moves whose power varies (their text says how). */
  power: number
  /** `true` for moves that never miss. */
  accuracy: number | true
  /** As Champions has it, PP Ups included. */
  pp: number
  priority: number
  target: Target
  /** `protect` means it goes through Protect. */
  flags: Flag[]
}

export const MOVES = DATA as unknown as Record<MoveId, Move>

/**
 * Whom a move reaches, in short, for the move rankings: Showdown's targets grouped by what they mean in a double
 * battle (its full target, `move.target.*`, says exactly whom).
 */
export const REACHES = ['one', 'foes', 'around', 'self', 'ally', 'side', 'foeSide', 'field'] as const
export type Reach = (typeof REACHES)[number]
const REACH: Record<Target, Reach> = {
  normal: 'one',
  any: 'one',
  randomNormal: 'one',
  scripted: 'one',
  allAdjacentFoes: 'foes',
  allAdjacent: 'around',
  self: 'self',
  adjacentAlly: 'ally',
  adjacentAllyOrSelf: 'ally',
  allies: 'side',
  allySide: 'side',
  allyTeam: 'side',
  foeSide: 'foeSide',
  all: 'field',
}
export const reachOf = (m: Move): Reach => REACH[m.target]

/** A move's priority as shown, when it has one: "+4", "−7" (a minus sign); null at 0. */
export const priorityLabel = (m: Move) =>
  m.priority > 0 ? `+${m.priority}` : m.priority < 0 ? `−${-m.priority}` : null

/** Moves that hit more than one Pokémon: their damage is reduced to 0.75× when they do. */
export const isSpread = (m: Move) => m.target === 'allAdjacentFoes' || m.target === 'allAdjacent'
